def test_bindings_are_inherited_from_base_widget_by_default():
    class A(DOMNode):
        BINDINGS = [("a", "a", "a")]

    class B(A):
        BINDINGS = [("b", "b", "b")]

    assert list(B()._bindings.keys.keys()) == ["a", "b"]


def test_inherit_bindings_false_with_own_bindings_clears_ancestor_bindings():
    class A(DOMNode):
        BINDINGS = [("a", "a", "a")]

    class B(A):
        BINDINGS = [("b", "b", "b")]

    class C(B, inherit_bindings=False):
        BINDINGS = [("c", "c", "c")]

    assert list(C()._bindings.keys.keys()) == ["c"]


def test_inherit_bindings_false_without_own_bindings_still_clears_ancestor_bindings():
    class A(DOMNode):
        BINDINGS = [("a", "a", "a")]

    class B(A):
        BINDINGS = [("b", "b", "b")]

    class C(B, inherit_bindings=False):
        BINDINGS = [("c", "c", "c")]

    class D(C, inherit_bindings=False):
