import pytest

from beets.autotag import mb


def _make_track(title, track_id, length):
    return {
        "title": title,
        "id": track_id,
        "length": length,
    }


def _make_release(tracks=None, medium_format="CD", medium_title=None):
    medium = {
        "format": medium_format,
        "track-list": tracks or [],
    }
    if medium_title is not None:
        medium["title"] = medium_title
    return {
        "medium-list": [medium],
    }


def test_album_info_includes_audio_medium_tracks():
    tracks = [
        _make_track("TITLE ONE", "ID ONE", 100.0 * 1000.0),
        _make_track("TITLE TWO", "ID TWO", 200.0 * 1000.0),
    ]
    release = _make_release(tracks=tracks, medium_format="CD")

    d = mb.album_info(release)

    assert len(d.tracks) == 2


