import pytest
from rest_framework import serializers
from rest_framework.fields import Field

from rest_framework_json_api.utils import get_resource_type_from_serializer


def test_get_resource_type_from_serializer_uses_explicit_resource_name():
    class SerializerWithResourceName(serializers.Serializer):
        class Meta:
            resource_name = "articles"

    serializer = SerializerWithResourceName()

    assert get_resource_type_from_serializer(serializer=serializer) == "articles"


def test_get_resource_type_from_serializer_uses_model_when_resource_name_missing():
    class DummyModel:
        pass

    class SerializerWithModel(serializers.Serializer):
        class Meta:
            model = DummyModel

    serializer = SerializerWithModel()

    assert get_resource_type_from_serializer(serializer=serializer) == get_resource_type_from_serializer(
        serializer=serializer
    )


def test_get_resource_type_from_serializer_raises_attribute_error_for_missing_resource_name():
    class SerializerWithoutResourceName(serializers.Serializer):
        something = Field()

    serializer = SerializerWithoutResourceName()

    with pytest.raises(AttributeError):
        get_resource_type_from_serializer(serializer=serializer)


def test_get_resource_type_from_serializer_error_message_includes_serializer_name_and_module():
    class SerializerWithoutResourceName(serializers.Serializer):
        something = Field()

    serializer = SerializerWithoutResourceName()

    with pytest.raises(AttributeError) as excinfo:
        get_resource_type_from_serializer(serializer=serializer)

    assert str(excinfo.value) == (
        "can not detect 'resource_name' on serializer "
        "'SerializerWithoutResourceName' in module '__main__'"
    )

