def test_augassign_custom_object_prefers___iadd___over___add__():
    class InPlaceAddOnly:
        def __init__(self):
            self.calls = 0

        def __iadd__(self, other):
            self.calls += 1
            return self

        def __add__(self, other):
            raise AssertionError("__add__ should not be used when __iadd__ exists")

    obj = InPlaceAddOnly()
    state = {"obj": obj}

    result, _ = evaluate_python_code("obj += 1", {}, state=state)

    assert result is obj
    assert obj.calls == 1


def test_augassign_subtraction_uses_inplace_subtraction_method():
    class InPlaceSubOnly:
        def __init__(self):
            self.calls = 0

        def __isub__(self, other):
            self.calls += 1
            return self

        def __sub__(self, other):
            raise AssertionError("__sub__ should not be used when __isub__ exists")

    obj = InPlaceSubOnly()
    state = {"obj": obj}

    result, _ = evaluate_python_code("obj -= 1", {}, state=state)

    assert result is obj
    assert obj.calls == 1


