from sympy import Function, Integer, symbols
from sympy.printing.precedence import PRECEDENCE


x, y = symbols("x y")


class LowPrecedenceF(Function):
    precedence = PRECEDENCE["Mul"] - 5

    def _sympystr(self, printer):
        return f"{printer._print(self.args[0])} F {printer._print(self.args[1])}"


class HighPrecedenceF(Function):
    precedence = PRECEDENCE["Func"]

    def _sympystr(self, printer):
        return f"{printer._print(self.args[0])} F {printer._print(self.args[1])}"


def test_mul_with_low_precedence_function_adds_parentheses():
    expr = Integer(2) * LowPrecedenceF(x, y)
    assert str(expr) == "2*(x F y)"


def test_negative_mul_with_low_precedence_function_adds_parentheses():
    expr = Integer(-2) * LowPrecedenceF(x, y)
    assert str(expr) == "-2*(x F y)"


def test_mul_with_high_precedence_function_keeps_flat_printing():
    expr = Integer(2) * HighPrecedenceF(x, y)
    assert str(expr) == "2*x F y"


def test_negative_mul_with_high_precedence_function_keeps_flat_printing():
    expr = Integer(-2) * HighPrecedenceF(x, y)
    assert str(expr) == "-2*x F y"

